#include <bits/stdc++.h>
using namespace std;
int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);
        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v; scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }
        vector<int> par(n+1,-1),dep(n+1,0),ord;
        vector<bool> vis(n+1,false);
        queue<int> bfs;
        bfs.push(1); vis[1]=true;
        while(!bfs.empty()){int u=bfs.front();bfs.pop();ord.push_back(u);
            for(auto[v,ei]:adj[u])if(!vis[v]){vis[v]=true;par[v]=u;dep[v]=dep[u]+1;bfs.push(v);}}
        int LOG=20;
        vector<vector<int>> up(LOG,vector<int>(n+1,0));
        for(int i=1;i<=n;i++) up[0][i]=(par[i]==-1?i:par[i]);
        for(int k=1;k<LOG;k++) for(int i=1;i<=n;i++) up[k][i]=up[k-1][up[k-1][i]];
        auto lca=[&](int a,int b)->int{
            if(dep[a]<dep[b]) swap(a,b);
            int d=dep[a]-dep[b];
            for(int k=0;k<LOG;k++) if((d>>k)&1) a=up[k][a];
            if(a==b) return a;
            for(int k=LOG-1;k>=0;k--) if(up[k][a]!=up[k][b]){a=up[k][a];b=up[k][b];}
            return up[0][a];
        };
        auto dist=[&](int a,int b)->int{return dep[a]+dep[b]-2*dep[lca(a,b)];};
        vector<vector<int>> results;
        for(int iter=0;iter<4*n&&iter<4000;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;
            vector<int> cands;
            for(int i=0;i<n-1;i++){
                int u=edges[i].first,v=edges[i].second;
                int before=dist(u,p[u])+dist(v,p[v]);
                int after=dist(u,p[v])+dist(v,p[u]);
                if(after<before) cands.push_back(i);
            }
            sort(cands.begin(),cands.end(),[&](int a,int b){
                int ua=edges[a].first,va=edges[a].second,ub=edges[b].first,vb=edges[b].second;
                int ga=dist(ua,p[ua])+dist(va,p[va])-dist(ua,p[va])-dist(va,p[ua]);
                int gb=dist(ub,p[ub])+dist(vb,p[vb])-dist(ub,p[vb])-dist(vb,p[ub]);
                return ga>gb;});
            vector<bool> used(n+1,false);
            vector<int> matching;
            for(int ei:cands){int u=edges[ei].first,v=edges[ei].second;
                if(!used[u]&&!used[v]){used[u]=used[v]=true;matching.push_back(ei);}}
            for(int ei:matching){int u=edges[ei].first,v=edges[ei].second;swap(p[u],p[v]);}
            if(matching.empty()){for(int i=0;i<n-1;i++){int u=edges[i].first,v=edges[i].second;
                if(p[u]!=u||p[v]!=v){matching.push_back(i);swap(p[u],p[v]);break;}}}
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto&m:results){printf("%d",(int)m.size());for(int ei:m) printf(" %d",ei+1);printf("\n");}
    }
}
